for (const l of Object.keys(EXTRA)) Object.assign(I18N[l], EXTRA[l]);

export const LANGS = { fr: "Français", en: "English", es: "Español", de: "Deutsch", it: "Italiano" };
export const DEFAULT_LANG = "fr";
export const isLang = (l) => Object.prototype.hasOwnProperty.call(LANGS, l);

export function translator(lang, site = "ContexteTech") {
  const dict = I18N[lang] || I18N.fr;
  return (k, v) => {
    let s = dict[k] ?? I18N.fr[k] ?? k;
    s = s.split("Contexthèque").join(site);
    if (v) for (const [a, b] of Object.entries(v)) s = s.split("{" + a + "}").join(String(b));
    return s;
  };
}

/** Sous-ensemble du dictionnaire transmis aux îlots Svelte */
export function pick(lang, keys) {
  const t = translator(lang);
  return Object.fromEntries(keys.map((k) => [k, t(k)]));
}

export function clangName(lang, c) {
  if (!c) return "";
  if (c === "multi") return translator(lang)("multilingual");
  try {
    const n = new Intl.DisplayNames([lang], { type: "language" }).of(c);
    return n.charAt(0).toUpperCase() + n.slice(1);
  } catch { return c; }
}

export function fmtNum(lang, n) {
  try { return new Intl.NumberFormat(lang, { notation: "compact" }).format(n || 0); } catch { return String(n || 0); }
}

export function ago(lang, ts) {
  if (!ts) return "";
  const d = (ts - Date.now()) / 1000, rtf = new Intl.RelativeTimeFormat(lang, { numeric: "auto" });
  if (Math.abs(d) < 3600) return rtf.format(Math.round(d / 60) || -1, "minute");
  if (Math.abs(d) < 86400) return rtf.format(Math.round(d / 3600), "hour");
  if (Math.abs(d) < 86400 * 30) return rtf.format(Math.round(d / 86400), "day");
  if (Math.abs(d) < 86400 * 365) return rtf.format(Math.round(d / 86400 / 30), "month");
  return rtf.format(Math.round(d / 86400 / 365), "year");
}

/** Choix de la langue à partir de l'en-tête Accept-Language */
export function negotiate(header) {
  for (const part of String(header || "").split(",")) {
    const code = part.trim().slice(0, 2).toLowerCase();
    if (isLang(code)) return code;
  }
  return DEFAULT_LANG;
}

/** Dictionnaire complet d'une langue (pour les îlots) */
export function dict(lang, site = "ContexteTech") {
  const t = translator(lang, site);
  return Object.fromEntries(Object.keys(I18N.fr).map((k) => [k, t(k)]));
}
